from html.parser import HTMLParser

class Contador(HTMLParser):
    enlaces = 0
    def handle_starttag(self, tag, attrs):
        if tag == "a":
            self.enlaces += 1

c = Contador()
c.feed('<nav><a href="/">Inicio</a> <a href="/blog">Blog</a></nav><p>Sin enlace</p>')
print(c.enlaces)
